def dose(ml):
    if ml <= 0:
        raise ValueError('positive only')
    return ml * 1.0

import math

DEFAULT_UNIT = 'ml'


def titrate(target_ph, current_ph, volume_l):
    delta = target_ph - current_ph
    return round(math.copysign(volume_l * abs(delta) * 0.15, delta), 3)


def schedule(doses):
    return sorted(doses, key=lambda d: d['at'])
